    if (code === 0) return resolve({ ok: true, out });
    const lines = out.trim().split('\n').map(s => s.trim()).filter(Boolean);
    resolve({ ok: false, error: (lines[lines.length - 1] || `tools/handoff.sh завершился с кодом ${code}`).slice(0, 300) });
