    s = io.open(f, encoding='utf-8').read()
    if decl_needed:
        n = s.count(DECL)
        assert n == 1, (f, 'decl', n)
        s = s.replace(DECL, DECL_NEW)
    old = RESTORE_OLD if decl_needed else """    <div id="runner-res"></div>
  </div>`;
